from pathlib import Path

p = Path('/app/app/atlas_manifest_runner.py')
s = p.read_text(encoding='utf-8')

old_discover_sig = '    async def _discover(self, client: httpx.AsyncClient, manifest: dict, scan_limit: int) -> tuple[list[str], list[dict]]:\n'
new_discover_sig = '    async def _discover(self, fetch_html, manifest: dict, scan_limit: int) -> tuple[list[str], list[dict]]:\n'
if old_discover_sig not in s:
    raise SystemExit('v22 patch failed: _discover signature not found')
s = s.replace(old_discover_sig, new_discover_sig, 1)
s = s.replace('                html = await self._fetch(client, start)\n', '                html = await fetch_html(start)\n', 1)
s = s.replace('                html = await self._fetch(client, hub)\n', '                html = await fetch_html(hub)\n', 1)

old_guard = '''        rendering = (manifest.get("crawl_rendering") or "http").lower()\n        if rendering not in {"http", "static", "html"}:\n            return {\n                "ok": False, "source_id": source_id, "reason": "rendering_not_supported_yet",\n                "crawl_rendering": rendering,\n            }\n\n        headers = {"User-Agent": USER_AGENT, "Accept-Language": "es,en;q=0.8"}\n        async with httpx.AsyncClient(timeout=self.timeout, follow_redirects=True, headers=headers) as client:\n            candidates, discovery_debug = await self._discover(client, manifest, scan_limit)\n            sem = asyncio.Semaphore(self.concurrency)\n\n            async def one(url: str):\n                async with sem:\n                    try:\n                        html = await self._fetch(client, url)\n                        item = extract_listing(manifest, url, html)\n                        return {"url": url, "item": item, "error": None}\n                    except Exception as exc:\n                        return {"url": url, "item": None, "error": str(exc)[:240]}\n\n            # Work in small waves and stop once enough valid vehicles are proven.\n            valid: list[dict] = []\n            attempted = 0\n            errors: list[dict] = []\n            wave = max(self.concurrency * 2, 8)\n            for i in range(0, len(candidates), wave):\n                batch = candidates[i:i + wave]\n                results = await asyncio.gather(*(one(u) for u in batch))\n                attempted += len(results)\n                for res in results:\n                    if res["error"]:\n                        errors.append({"url": res["url"], "error": res["error"]})\n                        continue\n                    item = res["item"] or {}\n                    if item.get("_required_ok"):\n                        valid.append(item)\n                        if len(valid) >= limit:\n                            break\n                if len(valid) >= limit:\n                    break\n'''
new_guard = '''        rendering = (manifest.get("crawl_rendering") or "http").lower()\n        if rendering not in {"http", "static", "html", "browser"}:\n            return {\n                "ok": False, "source_id": source_id, "reason": "rendering_not_supported",\n                "crawl_rendering": rendering,\n            }\n\n        headers = {"User-Agent": USER_AGENT, "Accept-Language": "es,en;q=0.8"}\n        sem = asyncio.Semaphore(self.concurrency)\n\n        async def execute(fetch_html):\n            candidates, discovery_debug = await self._discover(fetch_html, manifest, scan_limit)\n\n            async def one(url: str):\n                async with sem:\n                    try:\n                        html = await fetch_html(url)\n                        item = extract_listing(manifest, url, html)\n                        return {"url": url, "item": item, "error": None}\n                    except Exception as exc:\n                        return {"url": url, "item": None, "error": str(exc)[:240]}\n\n            valid: list[dict] = []\n            attempted = 0\n            errors: list[dict] = []\n            wave = max(self.concurrency * 2, 8)\n            for i in range(0, len(candidates), wave):\n                batch = candidates[i:i + wave]\n                results = await asyncio.gather(*(one(u) for u in batch))\n                attempted += len(results)\n                for res in results:\n                    if res["error"]:\n                        errors.append({"url": res["url"], "error": res["error"]})\n                        continue\n                    item = res["item"] or {}\n                    if item.get("_required_ok"):\n                        valid.append(item)\n                        if len(valid) >= limit:\n                            break\n                if len(valid) >= limit:\n                    break\n            return candidates, discovery_debug, valid, attempted, errors\n\n        if rendering == "browser":\n            from playwright.async_api import async_playwright\n            async with async_playwright() as pw:\n                browser = await pw.chromium.launch(headless=True)\n                context = await browser.new_context(\n                    user_agent=USER_AGENT,\n                    extra_http_headers={"Accept-Language": "es,en;q=0.8"},\n                )\n                async def fetch_html(url: str) -> str:\n                    page = await context.new_page()\n                    try:\n                        response = await page.goto(\n                            url, wait_until="domcontentloaded", timeout=int(self.timeout * 1000)\n                        )\n                        if response is not None and response.status >= 400:\n                            raise ValueError(f"http_status:{response.status}")\n                        await page.wait_for_timeout(750)\n                        return await page.content()\n                    finally:\n                        await page.close()\n                try:\n                    candidates, discovery_debug, valid, attempted, errors = await execute(fetch_html)\n                finally:\n                    await context.close()\n                    await browser.close()\n        else:\n            async with httpx.AsyncClient(timeout=self.timeout, follow_redirects=True, headers=headers) as client:\n                async def fetch_html(url: str) -> str:\n                    return await self._fetch(client, url)\n                candidates, discovery_debug, valid, attempted, errors = await execute(fetch_html)\n'''
if old_guard not in s:
    raise SystemExit('v22 patch failed: run rendering block not found')
s = s.replace(old_guard, new_guard, 1)
p.write_text(s, encoding='utf-8')
print('Applied Atlas runner v22 browser rendering support')
